head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // fn_HideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07301.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
    if (strBzProcsNo === "") {
        btn_Save.hide();
        await $c.win.alert("예비심사 내용을 저장 한 후에 예비심사절차를 등록하여 주십시오.");
    }
    txb_BZ_PROCS_NO.setValue(strBzProcsNo);
    url += "&BZ_PROCS_NO=" + strBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/konex/Prelisting.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sSEQ = txb_BYBZPROCS_SEQ.getValue();
    // alert(dts_Grid.Text);

    if (sSEQ === "") {
        // 추가모드.
        dts_Grid.insertRow(); // syncload = true;
        dts_Grid.setCellData(1, "BZ_PROCS_NO", strBzProcsNo);
        dts_Grid.setCellData(1, "STEP01", "0");
        dts_Grid.setCellData(1, "STEP02", "0");
        dts_Grid.setCellData(1, "STEP03", "0");
        dts_Grid.setCellData(1, "STEP04", "0");
        dts_Grid.setCellData(1, "STEP05", "0");
        dts_Grid.setCellData(1, "STEP06", "0");
        dts_Grid.setCellData(1, "STEP07", "0");
        dts_Grid.setCellData(1, "STEP08", "0");
        dts_Grid.setCellData(1, "STEP09", "0");
        dts_Grid.setCellData(1, "STEP10", "0");
        dts_Grid.setCellData(1, "STEP11", "0");
        dts_Grid.setCellData(1, "STEP12", "0");
        dts_Grid.setCellData(1, "STEP13", "0");
        dts_Grid.setCellData(1, "STEP14", "0");
        dts_Grid.setCellData(1, "STEP15", "0"); // 승인효력기간 추가 20100419
        dts_Grid.setCellData(1, "STEP16", "0"); // 상장예정일자 추가 20110110
        dts_Grid.setCellData(1, "STEP17", "0"); //
        dts_Grid.setCellData(1, "STEP18", "0"); //

    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07301.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_STEP12_DATE_onclick
 * @description btn_STEP12_DATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_STEP12_DATE_onclick = function() {
    try {
        popUpCalendar2(edt_STEP12_DATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07301.btn_STEP12_DATE_onclick" });
    }
};

