/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("저장에 실패하였습니다.");
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07301.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("저장하였습니다.");
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07301.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_STEP06_DATE_onclick
 * @description btn_STEP06_DATE 클릭 이벤트
 * @returns {void}
