    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (js_dep_cd.substring(0, 2) !== '25' && js_dep_cd.substring(0, 2) !== '33') {
        // 코스닥 심사팀

        // alert("해당 부서만 접수가 가능합니다."); return;

    }
    const sSTEP01 = dts_Grid.getCellData(1, "STEP01");
    const sSTEP02 = dts_Grid.getCellData(1, "STEP02");
    const sSTEP03 = dts_Grid.getCellData(1, "STEP03");
    const sSTEP04 = dts_Grid.getCellData(1, "STEP04");
    const sSTEP05 = dts_Grid.getCellData(1, "STEP05");
    const sSTEP06 = dts_Grid.getCellData(1, "STEP06");
    const sSTEP07 = dts_Grid.getCellData(1, "STEP07");
    const sSTEP08 = dts_Grid.getCellData(1, "STEP08");
    const sSTEP09 = dts_Grid.getCellData(1, "STEP09");
    const sSTEP10 = dts_Grid.getCellData(1, "STEP10");
    const sSTEP11 = dts_Grid.getCellData(1, "STEP11");
    const sSTEP12 = dts_Grid.getCellData(1, "STEP12");
    const sSTEP13 = dts_Grid.getCellData(1, "STEP13");
    const sSTEP14 = dts_Grid.getCellData(1, "STEP14");
    const sSTEP15 = dts_Grid.getCellData(1, "STEP15");
    const sSTEP16 = dts_Grid.getCellData(1, "STEP16");
    const sSTEP17 = dts_Grid.getCellData(1, "STEP17");
    const sSTEP18 = dts_Grid.getCellData(1, "STEP18");
    const cSTEP16 = dts_Grid.getCellData(1, "STEP16_DATE");
    const cSTEP07 = dts_Grid.getCellData(1, "STEP07_DATE");
    const cSTEP17 = dts_Grid.getCellData(1, "STEP17_DATE");
    const cSTEP18 = dts_Grid.getCellData(1, "STEP18_DATE");
    if (sSTEP01 === "0" && sSTEP02 === "0" &&
        sSTEP03 === "0" && sSTEP04 === "0" &&
        sSTEP05 === "0" && sSTEP06 === "0" &&
        sSTEP07 === "0" && sSTEP08 === "0" &&
        sSTEP09 === "0" && sSTEP10 === "0" &&
        sSTEP11 === "0" && sSTEP12 === "0" &&
        sSTEP13 === "0" && sSTEP14 === "0" &&
        sSTEP15 === "0" && sSTEP16 === "0" &&
        sSTEP17 === "0" && sSTEP18 === "0") {
        await $c.win.alert("저장할 상태가 없습니다.");
        return;
    }

    /*
    if (sSTEP09 == "1" || sSTEP10 == "1" || sSTEP11 == "1" ){

        var strListClss = getQuery(frame.srcUrl, "LIST_CLSS");
        if( strListClss != "재상장-인적분할"){
    		if ( sSTEP07 == "0"  || cSTEP07 == ""){
    			alert("증권신고서 제출일자를 입력하십시오.");
    			return;
    		}
    	}
    	if ( sSTEP16 == "0"  || cSTEP16 == ""){
    		alert("상장 예정일자를 입력하십시오.");
    		return;
    	}
    }
     */

    const res = window.confirm("상장신청 절차를 저장합니다.\n\n계속하시겠습니까?");
    if (res) {
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/konex/Prelisting.do",
            ref : "dts_Grid",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        // 청구서 접수일자를 업데이트 한다.
        /*
        trs_Save.Action   = "/lstinvstg/PrelmInvstg.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_02+"&method=modifyAcptDd";
        trs_Save.KeyName  = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_Save.Parameters  = "TRS_IDX=U" +
        								", ACPT_DD=" + edt_STEP01_DATE.GetSelClipText(0,8) +
        								", BZ_PROCS_NO="+ strBzProcsNo;

        trs_Save.Post();
         */

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {

};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
